import{_ as i,o as e,c as a,ag as s}from"./chunks/framework.ePeAWSvT.js";const m=JSON.parse('{"title":"MCP Container Optimization Roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"mcp-container-optimization.md","filePath":"mcp-container-optimization.md","lastUpdated":1773121716000}'),n={name:"mcp-container-optimization.md"};function r(o,t,d,l,p,h){return e(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="mcp-container-optimization-roadmap" tabindex="-1">MCP Container Optimization Roadmap <a class="header-anchor" href="#mcp-container-optimization-roadmap" aria-label="Permalink to &quot;MCP Container Optimization Roadmap&quot;">​</a></h1><blockquote><p>Baseline measured on Apple M2 Max (32 GB RAM, 12 cores), Docker Desktop 7.65 GB limit, 2 bots running.</p></blockquote><h2 id="current-state-per-bot-mcp-container" tabindex="-1">Current State (per bot MCP container) <a class="header-anchor" href="#current-state-per-bot-mcp-container" aria-label="Permalink to &quot;Current State (per bot MCP container)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Metric</th><th>Value</th></tr></thead><tbody><tr><td>Image</td><td><code>memohai/mcp:latest</code> (183 MB, alpine + Go + Node + Python + uv)</td></tr><tr><td>Process</td><td><code>/app/mcp</code> — Go gRPC server, 12 threads</td></tr><tr><td>RSS</td><td>~24 MB (15 MB anonymous + 9.5 MB file-mapped)</td></tr><tr><td>Binary</td><td>9.9 MB (Go, CGO_ENABLED=0)</td></tr><tr><td>Node.js</td><td>47.6 MB on disk</td></tr><tr><td>Python + uv</td><td>78 MB on disk</td></tr><tr><td>containerd snapshot</td><td>overlayfs, layers shared across bots</td></tr></tbody></table><h2 id="optimization-directions" tabindex="-1">Optimization Directions <a class="header-anchor" href="#optimization-directions" aria-label="Permalink to &quot;Optimization Directions&quot;">​</a></h2><h3 id="_1-lazy-start-stop-p0-—-done" tabindex="-1">1. Lazy Start / Stop (P0) — DONE <a class="header-anchor" href="#_1-lazy-start-stop-p0-—-done" aria-label="Permalink to &quot;1. Lazy Start / Stop (P0) — DONE&quot;">​</a></h3><p>See implementation in <code>internal/containerd/</code>. Containers start on-demand when a bot needs tool execution, and auto-stop after idle timeout.</p><h3 id="_2-reduce-gomaxprocs-p1" tabindex="-1">2. Reduce GOMAXPROCS (P1) <a class="header-anchor" href="#_2-reduce-gomaxprocs-p1" aria-label="Permalink to &quot;2. Reduce GOMAXPROCS (P1)&quot;">​</a></h3><p><strong>Effort</strong>: One environment variable change.</p><p>Each MCP container&#39;s Go runtime defaults <code>GOMAXPROCS</code> to the host CPU count (12 on M2 Max), creating ~12 OS threads per container. For a lightweight gRPC server this is excessive.</p><p><strong>Action</strong>: Set <code>GOMAXPROCS=1</code> (or <code>2</code>) in the container spec env.</p><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// in containerd container creation code, add to env:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;GOMAXPROCS=1&quot;</span></span></code></pre></div><p><strong>Expected impact</strong>:</p><ul><li>Threads per container: 12 → 3-4</li><li>500 bots: 6000 threads → ~2000</li><li>Slight memory reduction from fewer thread stacks (~8 KB each)</li></ul><h3 id="_3-slim-image-variant-p1" tabindex="-1">3. Slim Image Variant (P1) <a class="header-anchor" href="#_3-slim-image-variant-p1" aria-label="Permalink to &quot;3. Slim Image Variant (P1)&quot;">​</a></h3><p><strong>Effort</strong>: New Dockerfile, image selection logic.</p><p>Most bots only use the Go MCP binary. Node.js and Python are only needed when the bot has configured third-party MCP servers (npx/uvx).</p><p><strong>Action</strong>: Create <code>Dockerfile.mcp-slim</code> without Node/Python:</p><div class="language-dockerfile vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> alpine:latest</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> apk add --no-cache grep curl bash</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> --from=build /out/mcp /app/mcp</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cmd/mcp/entrypoint.sh /opt/entrypoint.sh</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> chmod +x /opt/entrypoint.sh</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ENTRYPOINT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/opt/entrypoint.sh&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p><strong>Expected impact</strong>:</p><ul><li>Image size: 183 MB → ~20 MB</li><li>RSS may drop ~5-10 MB (fewer file mappings)</li><li>Assign <code>mcp:slim</code> by default, <code>mcp:full</code> only for bots with third-party MCP configs</li></ul><h3 id="_4-cgroup-memory-limits-p2" tabindex="-1">4. cgroup Memory Limits (P2) <a class="header-anchor" href="#_4-cgroup-memory-limits-p2" aria-label="Permalink to &quot;4. cgroup Memory Limits (P2)&quot;">​</a></h3><p><strong>Effort</strong>: Configuration change in container spec.</p><p>Prevent runaway memory from individual containers (e.g., a bot running a heavy npm MCP server).</p><p><strong>Action</strong>: Set <code>memory.max</code> in the container&#39;s Linux resources spec:</p><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// in OCI spec creation:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">spec.Linux.Resources.Memory </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">specs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LinuxMemory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Limit: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">int64Ptr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">64</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1024</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1024</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 64 MB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>Expected impact</strong>:</p><ul><li>No change in normal operation</li><li>Prevents single container from consuming excessive memory</li><li>OOM-killed containers can be auto-restarted on next tool call (pairs well with lazy start/stop)</li></ul><h3 id="_5-shared-mcp-process-p3" tabindex="-1">5. Shared MCP Process (P3) <a class="header-anchor" href="#_5-shared-mcp-process-p3" aria-label="Permalink to &quot;5. Shared MCP Process (P3)&quot;">​</a></h3><p><strong>Effort</strong>: Major architecture change.</p><p>Instead of one container per bot, run a single MCP process that serves multiple bots, using filesystem namespaces (bind mounts) to isolate each bot&#39;s data directory.</p><p><strong>Design sketch</strong>:</p><ul><li>Single gRPC server with bot_id in request metadata</li><li>Mount <code>/data/{bot_id}</code> per-request working directory</li><li>Use Linux namespaces (unshare) for filesystem isolation without full container overhead</li></ul><p><strong>Expected impact</strong>:</p><ul><li>Memory: 500 × 24 MB → 1 × 24 MB + negligible per-bot overhead</li><li>Lose container-level isolation (security tradeoff)</li><li>Significant code changes to MCP server</li></ul><h2 id="priority-matrix" tabindex="-1">Priority Matrix <a class="header-anchor" href="#priority-matrix" aria-label="Permalink to &quot;Priority Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Priority</th><th>Direction</th><th>Effort</th><th>Memory Savings (500 bots)</th></tr></thead><tbody><tr><td>P0</td><td>Lazy start/stop</td><td>Medium</td><td>90% (50 active vs 500 idle)</td></tr><tr><td>P1</td><td>GOMAXPROCS=1</td><td>Trivial</td><td>~5% per container</td></tr><tr><td>P1</td><td>Slim image</td><td>Small</td><td>~5-10 MB per container</td></tr><tr><td>P2</td><td>cgroup limits</td><td>Small</td><td>Safety net, no direct savings</td></tr><tr><td>P3</td><td>Shared process</td><td>Large</td><td>~95%+</td></tr></tbody></table><h2 id="hardware-reference" tabindex="-1">Hardware Reference <a class="header-anchor" href="#hardware-reference" aria-label="Permalink to &quot;Hardware Reference&quot;">​</a></h2><p>To run N <strong>concurrent</strong> MCP containers (assuming ~24 MB each with current image):</p><table tabindex="0"><thead><tr><th>Concurrent Containers</th><th>RAM Needed (containers only)</th><th>Recommended Total RAM</th></tr></thead><tbody><tr><td>50</td><td>1.2 GB</td><td>8 GB</td></tr><tr><td>100</td><td>2.4 GB</td><td>16 GB</td></tr><tr><td>250</td><td>6 GB</td><td>32 GB</td></tr><tr><td>500</td><td>12 GB</td><td>64 GB</td></tr></tbody></table><p>With lazy start/stop, &quot;concurrent&quot; = bots actively executing tools, not total bot count.</p>`,41)])])}const k=i(n,[["render",r]]);export{m as __pageData,k as default};
